/// Calculates the area of a circle given its radius.
///
/// # Example
/// ```
/// let area = circle_area(5.0)
/// assert_approx(area, 78.5398, 0.001)
/// ```
pub fn circle_area(radius: Float64) -> Float64 {
    return 3.14159 * radius * radius
}

