//! # Math Utils
//! A collection of mathematical utility functions.
//! This crate provides geometry, statistics, and number theory helpers.

/// Represents a point in 2D space.
pub struct Point {
    /// The x-coordinate.
    pub x: Float64,
    /// The y-coordinate.
    pub y: Float64,
}

/// Computes the Euclidean distance between two points.
///
/// # Arguments
/// * `a` - The first point
/// * `b` - The second point
///
/// # Returns
/// The straight-line distance between `a` and `b`.
pub fn distance(a: &Point, b: &Point) -> Float64 {
    let dx = a.x - b.x
    let dy = a.y - b.y
    return (dx * dx + dy * dy).sqrt()
}
